        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        uint256 depositsAfter = c.depositsCount();
        uint256 balanceAfter = address(c).balance;

        // The number of fallback calls during sendMoney equals (balanceBefore - balanceAfter - value) / value? 
