pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // restrict value to not overflow
        value = bound(value, 0, address(this).balance);
        // fund the contract with some ether for the test
        vm.deal(address(c), 1 ether);

        // capture the effect of calling sendMoney
        bool sendReverted;
        try c.sendMoney{value: value}(target, value) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // call withdrawAll – reference would actually withdraw, mutant would not
        // After sendMoney, the contract's balance may change, but withdrawAll's behavior
        // should be consistent: in reference, calling withdrawAll reduces balance to 0;
        // in mutant it does nothing. We check that after calling withdrawAll, the
        // contract's balance is 0 iff the call succeeded (and didn't revert) – but
        // for generality, compare the effect of withdrawing after sendMoney vs before.
        // Simpler: record balance before withdrawAll
        uint256 balBefore = address(c).balance;
        c.withdrawAll();
        uint256 balAfter = address(c).balance;

        // General rule: after sendMoney, calling withdrawAll should transfer all ether out
        // (unless there is a revert). So the post-withdrawAll balance must be 0.
        // This holds for the reference (withdrawAll works) and fails for the mutant (does nothing).
        assertTrue(balAfter == 0 || sendReverted, "after sendMoney, withdrawAll should empty the contract");
    }
}

