pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Record the initial return value of withdraw for any given value
        // (This test assumes value is the same as what will be passed to sendMoney)
        // To avoid infinite loop or revert, bound value to a reasonable range
        vm.assume(value <= 100 ether && value > 0);
        vm.assume(target != address(0) && target != address(c));

        // Fund contract so withdraw can succeed
        vm.deal(address(c), value + 1 ether);

        uint256 initialWithdraw = c.withdraw(value); // call withdraw with the same value
        // Now call sendMoney to trigger the bug
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        vm.assume(success); // ensure sendMoney does not revert

        // Check that withdraw returns the same value after sendMoney
        uint256 finalWithdraw = c.withdraw(value);
        assertTrue(initialWithdraw == finalWithdraw, "withdraw changed after sendMoney");
    }
}

